/// Dart's `String` methods, under their Dart names, on Rust's `String`.
///
/// The backend spells a Dart call `s.codeUnitAt(i)` as `s.code_unit_at(i)`
/// and stops there; this trait is where those names land. Only names `str`
/// does not already have: a trait method on `String` shadows a `str` one,
/// and `split`/`contains`/`trim` here broke the fixtures that used them. Lengths and
/// indices are in UTF-16 code units, as Dart's are -- `len()` would have
/// counted bytes, and "length" is the commonest String member in the
/// gallery (19 sites in the leaf crates alone).
pub trait DartString {
    fn length(&self) -> i64;
    fn code_unit_at(&self, index: i64) -> i64;
    fn substring(&self, start: i64, end: Option<i64>) -> String;
    fn to_lower_case(&self) -> String;
    fn to_upper_case(&self) -> String;
    /// `indexOf(pattern, [start = 0])`: the default is filled in by the
    /// front end, so `start` is never absent here.
    fn index_of(&self, other: String, start: i64) -> i64;
    fn replace_all(&self, from: String, to: String) -> String;
    fn is_not_empty(&self) -> bool;
    fn pad_left(&self, width: i64, padding: String) -> String;
    fn pad_right(&self, width: i64, padding: String) -> String;
    fn code_units(&self) -> Vec<i64>;
    /// `replaceRange(start, end, replacement)`: a new string.
    fn replace_range_dart(&self, start: i64, end: Option<i64>, replacement: String) -> String;
    /// `startsWith(pattern, index)`.
    fn starts_with_at(&self, pattern: String, index: i64) -> bool;
    /// `contains(other, [startIndex])`: Rust's `contains` wants a `&str`
    /// and has no start.
    fn contains_dart(&self, pattern: String, start: i64) -> bool;
    /// `'0' * n`.
    fn repeat_dart(&self, times: i64) -> String;
    /// `split(pattern)`, into owned pieces.
    fn split_dart(&self, pattern: String) -> Vec<String>;
    /// `s[i]`: the one-code-unit String at `i`.
    fn char_at(&self, index: i64) -> String;
    /// `trim()`/`trimLeft()`/`trimRight()`, owned.
    fn trim_dart(&self) -> String;
    fn trim_left_dart(&self) -> String;
    fn trim_right_dart(&self) -> String;
    /// `hashCode`: stable within a process, not Dart's numbers.
    fn hash_code(&self) -> i64;
}

impl DartString for String {
    fn length(&self) -> i64 {
        self.encode_utf16().count() as i64
    }

    fn code_unit_at(&self, index: i64) -> i64 {
        self.encode_utf16()
            .nth(index as usize)
            .map(|u| u as i64)
            .unwrap_or(0)
    }

    fn substring(&self, start: i64, end: Option<i64>) -> String {
        let units: Vec<u16> = self.encode_utf16().collect();
        let end = end
            .map(|e| e as usize)
            .unwrap_or(units.len())
            .min(units.len());
        let start = (start.max(0) as usize).min(end);
        String::from_utf16_lossy(&units[start..end])
    }

    fn to_lower_case(&self) -> String {
        self.to_lowercase()
    }

    fn to_upper_case(&self) -> String {
        self.to_uppercase()
    }

    fn index_of(&self, other: String, start: i64) -> i64 {
        let units: Vec<u16> = self.encode_utf16().collect();
        let needle: Vec<u16> = other.encode_utf16().collect();
        let from = start.max(0) as usize;
        if needle.is_empty() {
            return from.min(units.len()) as i64;
        }
        (from..units.len().saturating_sub(needle.len() - 1))
            .find(|&i| units[i..i + needle.len()] == needle[..])
            .map(|i| i as i64)
            .unwrap_or(-1)
    }

    fn replace_all(&self, from: String, to: String) -> String {
        str::replace(self, from.as_str(), to.as_str())
    }

    fn is_not_empty(&self) -> bool {
        !str::is_empty(self)
    }

    fn pad_left(&self, width: i64, padding: String) -> String {
        let mut out = String::new();
        let mut n = DartString::length(self);
        while n < width {
            out.push_str(&padding);
            n += DartString::length(&padding).max(1);
        }
        out.push_str(self);
        out
    }

    fn pad_right(&self, width: i64, padding: String) -> String {
        let mut out = self.clone();
        let mut n = DartString::length(self);
        while n < width {
            out.push_str(&padding);
            n += DartString::length(&padding).max(1);
        }
        out
    }

    fn code_units(&self) -> Vec<i64> {
        self.encode_utf16().map(|u| u as i64).collect()
    }

    fn hash_code(&self) -> i64 {
        use std::hash::{Hash, Hasher};
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        self.hash(&mut hasher);
        (hasher.finish() & 0x3fff_ffff) as i64
    }

    fn trim_dart(&self) -> String {
        self.trim().to_string()
    }
    fn trim_left_dart(&self) -> String {
        self.trim_start().to_string()
    }
    fn trim_right_dart(&self) -> String {
        self.trim_end().to_string()
    }

    fn char_at(&self, index: i64) -> String {
        let units: Vec<u16> = self.encode_utf16().collect();
        String::from_utf16_lossy(&units[index as usize..index as usize + 1])
    }

    fn split_dart(&self, pattern: String) -> Vec<String> {
        let s: &str = self.as_ref();
        if pattern.is_empty() {
            return s.chars().map(|c| c.to_string()).collect();
        }
        s.split(pattern.as_str()).map(|p| p.to_string()).collect()
    }
    fn repeat_dart(&self, times: i64) -> String {
        let s: &str = self.as_ref();
        s.repeat(times.max(0) as usize)
    }
    fn contains_dart(&self, pattern: String, start: i64) -> bool {
        let s: &str = self.as_ref();
        let from = s
            .char_indices()
            .nth(start.max(0) as usize)
            .map(|(i, _)| i)
            .unwrap_or(s.len());
        s[from..].contains(pattern.as_str())
    }
    fn starts_with_at(&self, pattern: String, index: i64) -> bool {
        let units: Vec<u16> = self.encode_utf16().collect();
        let needle: Vec<u16> = pattern.encode_utf16().collect();
        let from = index.max(0) as usize;
        from + needle.len() <= units.len() && units[from..from + needle.len()] == needle[..]
    }

    fn replace_range_dart(&self, start: i64, end: Option<i64>, replacement: String) -> String {
        let end = end.unwrap_or(self.length());
        let units: Vec<u16> = self.encode_utf16().collect();
        let end = (end.max(0) as usize).min(units.len());
        let start = (start.max(0) as usize).min(end);
        let mut out = String::from_utf16_lossy(&units[..start]);
        out.push_str(&replacement);
        out.push_str(&String::from_utf16_lossy(&units[end..]));
        out
    }
}

/// `dart:ui`'s native hooks, which upstream implements in C++ behind
/// `external` declarations. `_print` is stdout; `_scheduleMicrotask` runs
/// the callback *now* -- there is no event loop here to run it after the
/// current turn, and "now" is the ordering a single-threaded program can
/// observe least. This is where to look when something depended on the
/// delay.
pub fn _print(arg: String) {
    println!("{}", arg);
}

pub fn _print_debug(arg: String) {
    eprintln!("{}", arg);
}

pub fn _schedule_microtask(callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>) {
    // An error out of a microtask has no caller to reach: loud.
    callback().unwrap();
}

/// `dart:core`'s `_StringStackTrace`, a stack trace that is just text: the
/// same type, so it goes where a `StackTrace` is wanted.
pub type _StringStackTrace = StackTrace;

/// `dart:io`'s `InternetAddress`, as far as `dart:ui` asks of it: whether a
/// host is the loopback.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct InternetAddress {
    pub host: String,
}

impl InternetAddress {
    /// `InternetAddress(address, {type})`: the type is a hint this stub
    /// does not need.
    pub fn new(host: String, _type: Option<i64>) -> Self {
        InternetAddress { host }
    }

    pub fn is_loopback(&self) -> bool {
        self.host == "localhost" || self.host.starts_with("127.") || self.host == "::1"
    }
}

/// `dart:core`'s `_Uri`: the class `Uri(..)` constructs behind the
/// interface. Nine optional parts, assembled into the one string this
/// prelude's `Uri` keeps.
pub struct _Uri;

impl _Uri {
    pub fn new(
        scheme: Option<String>,
        user_info: Option<String>,
        host: Option<String>,
        port: Option<i64>,
        path: Option<String>,
        path_segments: Option<Vec<String>>,
        query: Option<String>,
        query_parameters: Option<Map<String, std::rc::Rc<dyn Object>>>,
        fragment: Option<String>,
    ) -> Uri {
        let _ = query_parameters;
        let mut text = String::new();
        if let Some(s) = scheme {
            text.push_str(&s);
            text.push(':');
        }
        if host.is_some() || user_info.is_some() {
            text.push_str("//");
            if let Some(u) = user_info {
                text.push_str(&u);
                text.push('@');
            }
            if let Some(h) = host {
                text.push_str(&h);
            }
            if let Some(p) = port {
                text.push_str(&format!(":{}", p));
            }
        }
        match (path, path_segments) {
            (Some(p), _) => text.push_str(&p),
            (None, Some(segments)) => text.push_str(&segments.join("/")),
            (None, None) => {}
        }
        if let Some(q) = query {
            text.push('?');
            text.push_str(&q);
        }
        if let Some(f) = fragment {
            text.push('#');
            text.push_str(&f);
        }
        Uri { text }
    }
}

/// `Object.hash(a, b, ..)`: up to twenty parts, the unused ones arriving
/// as `SentinelValue`. Over the debug text of each, as `object_hash_all`.
pub fn object_hash<
    A: std::fmt::Debug,
    B: std::fmt::Debug,
    C: std::fmt::Debug,
    D: std::fmt::Debug,
    E: std::fmt::Debug,
    F: std::fmt::Debug,
    G: std::fmt::Debug,
    H: std::fmt::Debug,
    I: std::fmt::Debug,
    J: std::fmt::Debug,
    K: std::fmt::Debug,
    L: std::fmt::Debug,
    M: std::fmt::Debug,
    N: std::fmt::Debug,
    O: std::fmt::Debug,
    P: std::fmt::Debug,
    Q: std::fmt::Debug,
    R: std::fmt::Debug,
    S: std::fmt::Debug,
    T: std::fmt::Debug,
>(
    a: A,
    b: B,
    c: C,
    d: D,
    e: E,
    f: F,
    g: G,
    h: H,
    i: I,
    j: J,
    k: K,
    l: L,
    m: M,
    n: N,
    o: O,
    p: P,
    q: Q,
    r: R,
    s: S,
    t: T,
) -> i64 {
    use std::hash::{Hash, Hasher};
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    format!("{:?}", a).hash(&mut hasher);
    format!("{:?}", b).hash(&mut hasher);
    format!("{:?}", c).hash(&mut hasher);
    format!("{:?}", d).hash(&mut hasher);
    format!("{:?}", e).hash(&mut hasher);
    format!("{:?}", f).hash(&mut hasher);
    format!("{:?}", g).hash(&mut hasher);
    format!("{:?}", h).hash(&mut hasher);
    format!("{:?}", i).hash(&mut hasher);
    format!("{:?}", j).hash(&mut hasher);
    format!("{:?}", k).hash(&mut hasher);
    format!("{:?}", l).hash(&mut hasher);
    format!("{:?}", m).hash(&mut hasher);
    format!("{:?}", n).hash(&mut hasher);
    format!("{:?}", o).hash(&mut hasher);
    format!("{:?}", p).hash(&mut hasher);
    format!("{:?}", q).hash(&mut hasher);
    format!("{:?}", r).hash(&mut hasher);
    format!("{:?}", s).hash(&mut hasher);
    format!("{:?}", t).hash(&mut hasher);
    (hasher.finish() >> 1) as i64
}

/// `Object.hashAll(xs)`: a hash of the elements in order. Over the debug
/// text of each element, which is not Dart's algorithm and does not need to
/// be -- nothing here persists a hash -- and which every element type here
/// can produce.
pub fn object_hash_all<T: std::fmt::Debug>(items: Vec<T>) -> i64 {
    use std::hash::{Hash, Hasher};
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    for item in &items {
        format!("{:?}", item).hash(&mut hasher);
    }
    (hasher.finish() >> 1) as i64
}

/// More of `dart:ui`'s hooks: the callback-handle registry, which nothing
/// here uses across an isolate boundary, so there are no handles.
/// `_invoke1WithReturn<A, R>(R Function(A)? callback, Zone? zone, A arg)`:
/// `R?`, null when there is no callback.
pub fn _invoke1_with_return<A, R>(
    callback: Option<std::rc::Rc<dyn Fn(A) -> Result<R, DartError>>>,
    _zone: Zone,
    arg: A,
) -> Result<Option<R>, DartError> {
    callback.map(|f| f(arg)).transpose()
}

#[allow(dead_code)]
fn _invoke1_with_return_unused<A, R>(
    callback: std::rc::Rc<dyn Fn(A) -> Result<R, DartError>>,
    _zone: Zone,
    arg: A,
) -> Result<R, DartError> {
    callback(arg)
}

pub fn _get_callback_handle(_callback: std::rc::Rc<dyn Object>) -> Option<i64> {
    None
}

pub fn _get_callback_from_handle(_handle: i64) -> Option<std::rc::Rc<dyn Object>> {
    None
}

/// A value in a string interpolation, when it is not a string or a number:
/// Dart calls `toString()`, and the translated classes carry theirs as
/// `Debug`. Not the same text -- `Offset { dx: 1.0, dy: 2.0 }` where Dart
/// prints `Offset(1.0, 2.0)` -- and nothing here reads it back. 57 parts
/// `cannot be formatted with the default formatter`.
pub fn dart_str<T: std::fmt::Debug>(value: T) -> String {
    format!("{:?}", value)
}

/// Dart's `Symbol`: a member name as a value.
///
/// `#foo` in source, and what `Invocation.memberName` carries. Compared and
/// printed, nothing else -- there is no `dart:mirrors` here to look a name up
/// with. Prints as Dart prints it, `Symbol("foo")`, because the one reader of
/// it in this program interpolates it into an error message.
///
/// A private symbol (`#_start`) is private *to a library* in Dart, and two
/// libraries' `#_start` are different symbols. The library is dropped here: a
/// name is all a `Symbol` holds. Nothing in this program compares symbols
/// across libraries, and this is where to look when something does.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Symbol {
    pub name: &'static str,
}

impl Symbol {
    pub const fn of(name: &'static str) -> Self {
        Symbol { name }
    }
}

impl fmt::Display for Symbol {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Symbol(\"{}\")", self.name)
    }
}

/// A `Never` value, turned into whatever the caller needed.
///
/// Dart's `Never` is spelled `std::convert::Infallible` here (see the
/// backend's type map), and an `Infallible` does not coerce the way `!`
/// would: a getter declared `-> bool` cannot return one. `match x {}` on an
/// empty enum has every type at once, which is what `!` meant. The
/// `noSuchMethod` forwarders are where this is called.
pub fn never<T>(x: std::convert::Infallible) -> T {
    match x {}
}

/// Dart's `Invocation`: what `noSuchMethod` is handed.
///
/// The CFE writes one *forwarder* per interface member of a class that
/// declares `noSuchMethod` -- `_WidgetTextStyleMapper` gets thirty-four -- and
/// each builds one of these and passes it on. Measured across `package:` on
/// 2026-09-03: every `noSuchMethod` in the program reads exactly one thing off
/// it, `memberName`. So that is what it carries, with the kind beside it. The
/// positional, named and type arguments are **not** here: a `noSuchMethod`
/// that reads them would get nothing, and this struct is where to add them.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Invocation {
    pub member_name: Symbol,
    pub kind: InvocationKind,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum InvocationKind {
    Method,
    Getter,
    Setter,
}

impl Invocation {
    pub const fn getter(member_name: Symbol) -> Self {
        Invocation {
            member_name,
            kind: InvocationKind::Getter,
        }
    }

    pub const fn setter(member_name: Symbol) -> Self {
        Invocation {
            member_name,
            kind: InvocationKind::Setter,
        }
    }

    pub const fn method(member_name: Symbol) -> Self {
        Invocation {
            member_name,
            kind: InvocationKind::Method,
        }
    }

    pub fn member_name(&self) -> Symbol {
        self.member_name
    }

    pub fn is_getter(&self) -> bool {
        matches!(self.kind, InvocationKind::Getter)
    }

    pub fn is_setter(&self) -> bool {
        matches!(self.kind, InvocationKind::Setter)
    }

    pub fn is_method(&self) -> bool {
        matches!(self.kind, InvocationKind::Method)
    }
}

/// Dart's `Zone`.
///
/// A zone is the async context a callback was registered in, so that running
/// it later runs it under the same error handling. Upstream stores one beside
/// each callback -- `dart:ui` keeps a `_zone` next to every platform handler --
/// and then runs the callback in it.
///
/// There is exactly one zone here, because there is no runtime to make a
/// second: `Zone::CURRENT` is it, and `run` calls the callback directly. That
/// is what the root zone does in Dart too. A program that installs a zone of
/// its own to catch errors would not get that behaviour, and this is where to
/// look when it does not.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Zone;

impl Zone {
    /// `Zone.current`, a static getter upstream and so a call here.
    /// `Zone.root`: the one zone there is here.
    pub fn root() -> Zone {
        Zone::current()
    }

    pub fn current() -> Zone {
        Zone
    }

    pub const CURRENT: Zone = Zone;

    pub fn run<T>(&self, body: impl FnOnce() -> Result<T, DartError>) -> Result<T, DartError> {
        body()
    }

    /// `Zone.current[key]`: a `dynamic`, which is never an `Option` here;
    /// the root zone holds no values, so this is Dart's `null` as an object.
    pub fn index_of<K>(&self, _key: K) -> std::rc::Rc<dyn Object> {
        std::rc::Rc::new(Null)
    }

    /// `runGuarded(f)`: the root zone has no error handler to guard with.
    pub fn run_guarded(
        &self,
        body: std::rc::Rc<dyn Fn() -> Result<(), DartError>>,
    ) -> Result<(), DartError> {
        body()
    }

    /// `runUnaryGuarded(f, arg)`.
    pub fn run_unary_guarded<A>(
        &self,
        body: std::rc::Rc<dyn Fn(A) -> Result<(), DartError>>,
        arg: A,
    ) -> Result<(), DartError> {
        body(arg)
    }

    pub fn run_unary<A, T>(
        &self,
        body: impl FnOnce(A) -> Result<T, DartError>,
        argument: A,
    ) -> Result<T, DartError> {
        body(argument)
    }

    pub fn register_callback<T>(
        &self,
        body: impl Fn() -> Result<T, DartError>,
    ) -> impl Fn() -> Result<T, DartError> {
        body
    }
}

/// The isolate's event loop: microtasks, then timers, the way Dart's runs.
///
/// This is the smallest thing that can honestly be called a scheduler. It is
/// here because the translated code *uses* `Timer` -- 37 places name it -- and
/// a type that records nothing would be a stub. What is not here is anybody
/// calling `run_until_idle`: a translated `main` would, and there is no
/// translated `main` yet. That gap is the loop's, not the timer's.
///
/// Dart's ordering is kept because programs depend on it: every microtask
/// drains before any timer runs, and a microtask queued by a microtask runs
/// before the timers too.
pub struct Scheduler {
    microtasks: std::collections::VecDeque<Box<dyn FnOnce() -> Result<(), DartError>>>,
    timers: Vec<Scheduled>,
    next_id: i64,
    /// Futures running on their own (`dart_spawn`): Dart's are eager, and
    /// a `Future(..)` nobody awaits still runs.
    tasks: Vec<std::pin::Pin<std::boxed::Box<dyn std::future::Future<Output = ()>>>>,
}

/// Set by any waker the scheduler hands out: something a task or `main`
/// awaited has moved on, so another pass is worth making.
struct Woken(std::sync::atomic::AtomicBool);

impl std::task::Wake for Woken {
    fn wake(self: std::sync::Arc<Self>) {
        self.0.store(true, std::sync::atomic::Ordering::Relaxed);
    }
}

pub static WOKEN: std::sync::LazyLock<std::sync::Arc<Woken>> = std::sync::LazyLock::new(|| {
    std::sync::Arc::new(Woken(std::sync::atomic::AtomicBool::new(false)))
});

/// The scheduler's waker, and whether anything woke since it was last asked.
pub fn dart_waker() -> std::task::Waker {
    std::task::Waker::from(std::sync::Arc::clone(&*WOKEN))
}

pub fn dart_woken() -> bool {
    WOKEN.0.swap(false, std::sync::atomic::Ordering::Relaxed)
}

/// A Dart `Future<T>`: a shared handle on a result that arrives once, which
/// any number of holders may clone, store, and await (each awaiter gets a
/// clone of the result). A translated `async` function returns one, made
/// by `spawn`: its body runs on the scheduler from the next pass, whether
/// or not anything awaits it, as Dart's does.
pub struct DartFuture<T> {
    shared: std::rc::Rc<std::cell::RefCell<FutureState<T>>>,
}

struct FutureState<T> {
    result: Option<Result<T, DartError>>,
    wakers: Vec<std::task::Waker>,
}

impl<T> Clone for DartFuture<T> {
    fn clone(&self) -> Self {
        DartFuture {
            shared: self.shared.clone(),
        }
    }
}

impl<T> std::fmt::Debug for DartFuture<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'Future'")
    }
}

/// By identity, as Dart's `==` on a future is.
impl<T> PartialEq for DartFuture<T> {
    fn eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.shared, &other.shared)
    }
}

impl<T> DartNullable for DartFuture<T> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

impl<T> DartFuture<T> {
    /// A future nothing has resolved yet (a `Completer`'s).
    pub fn pending() -> Self {
        DartFuture {
            shared: std::rc::Rc::new(std::cell::RefCell::new(FutureState {
                result: None,
                wakers: Vec::new(),
            })),
        }
    }

    /// `Future.value(v)` / `Future.error(e)`: already done.
    pub fn ready(result: Result<T, DartError>) -> Self {
        let future = DartFuture::pending();
        future.resolve(result);
        future
    }

    pub fn is_done(&self) -> bool {
        self.shared.borrow().result.is_some()
    }

    /// Resolves it, once, and wakes everything awaiting it.
    pub fn resolve(&self, result: Result<T, DartError>) {
        let wakers = {
            let mut state = self.shared.borrow_mut();
            if state.result.is_some() {
                panic!("a Future resolved twice");
            }
            state.result = Some(result);
            std::mem::take(&mut state.wakers)
        };
        for waker in wakers {
            waker.wake();
        }
    }

    /// Runs `future` on the scheduler and hands back the future of its
    /// result: Dart's futures are eager, and a `Future(..)` nobody awaits
    /// still runs.
    pub fn spawn(
        future: std::pin::Pin<
            std::boxed::Box<dyn std::future::Future<Output = Result<T, DartError>>>,
        >,
    ) -> Self
    where
        T: 'static,
    {
        let out = DartFuture::pending();
        let done = out.clone();
        let mut future = future;
        (**SCHEDULER).borrow_mut().tasks.push(Box::pin(async move {
            let result = future.as_mut().await;
            done.resolve(result);
        }));
        out
    }

    /// `future.then(onValue, onError: ..)`: the error goes to `onError` when
    /// there is one, and on through the returned future when there is not.
    pub fn then<R: 'static>(
        &self,
        on_value: std::rc::Rc<dyn Fn(T) -> Result<R, DartError>>,
        on_error: Option<std::rc::Rc<dyn Fn(DartError) -> Result<R, DartError>>>,
    ) -> DartFuture<R>
    where
        T: Clone + 'static,
    {
        let me = self.clone();
        DartFuture::spawn(Box::pin(async move {
            match me.await {
                Ok(value) => on_value(value),
                Err(error) => match on_error {
                    Some(handler) => handler(error),
                    None => Err(error),
                },
            }
        }))
    }
}

impl<T: Clone> std::future::Future for DartFuture<T> {
    type Output = Result<T, DartError>;

    fn poll(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Self::Output> {
        let mut state = self.shared.borrow_mut();
        match &state.result {
            Some(result) => std::task::Poll::Ready(result.clone()),
            None => {
                state.wakers.push(cx.waker().clone());
                std::task::Poll::Pending
            }
        }
    }
}

/// `DartFuture::spawn`, as a function.
pub fn dart_spawn<T: 'static>(
    future: std::pin::Pin<std::boxed::Box<dyn std::future::Future<Output = Result<T, DartError>>>>,
) -> DartFuture<T> {
    DartFuture::spawn(future)
}

/// A future that completes when the timer fires.
pub fn timer_future(delay: Duration) -> DartFuture<()> {
    let future = DartFuture::pending();
    let done = future.clone();
    Timer::new(
        delay,
        std::rc::Rc::new(move || {
            done.resolve(Ok(()));
            Ok(())
        }),
    );
    future
}

/// `Future(computation)`: the computation runs on the scheduler's next pass.
pub fn future_new<T: Clone + 'static>(
    computation: std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>,
) -> DartFuture<T> {
    DartFuture::spawn(Box::pin(async move { computation()?.await }))
}

/// `Future.value([value])`: already done. The parameter is Dart's
/// `FutureOr<T>? value`, and what arrives is the `T` in an `Option` (the
/// front end coerces a plain value into the optional slot); no value is
/// the `null` of `T` -- `()` for a `Future<void>`.
pub fn future_value<T: DartNullable>(value: Option<T>) -> DartFuture<T> {
    DartFuture::ready(Ok(value
        .or_else(T::dart_null)
        .expect("Future.value() without a value on a non-nullable type")))
}

/// `Future.microtask(computation)`: the same, one pass is a microtask here.
pub fn future_microtask<T: Clone + 'static>(
    computation: std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>,
) -> DartFuture<T> {
    future_new(computation)
}

/// `Future.sync(computation)`: the computation runs now; its value or its
/// future is the result.
pub fn future_sync<T: Clone + 'static>(
    computation: std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>,
) -> DartFuture<T> {
    match computation() {
        Ok(FutureOr::Value(value)) => DartFuture::ready(Ok(value.expect("FutureOr value"))),
        Ok(FutureOr::Future(future)) => future,
        Err(error) => DartFuture::ready(Err(error)),
    }
}

/// `Future.delayed(duration, [computation])`: after the timer, the
/// computation's result, or `null` when there is none.
pub fn future_delayed<T: DartNullable + Clone + 'static>(
    duration: Duration,
    computation: Option<std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>>,
) -> DartFuture<T> {
    DartFuture::spawn(Box::pin(async move {
        timer_future(duration).await?;
        match computation {
            Some(computation) => computation()?.await,
            None => Ok(T::dart_null()
                .expect("Future.delayed without a computation on a non-nullable type")),
        }
    }))
}

/// `Future.wait(futures)`: every result, in order.
pub fn future_wait<T: Clone + 'static>(futures: Vec<DartFuture<T>>) -> DartFuture<Vec<T>> {
    DartFuture::spawn(Box::pin(async move {
        let mut out = Vec::new();
        for future in futures {
            out.push(future.await?);
        }
        Ok(out)
    }))
}

/// Dart's `FutureOr<T>`: a `T`, or a `Future<T>`; awaitable either way.
pub enum FutureOr<T> {
    Value(Option<T>),
    Future(DartFuture<T>),
}

impl<T> FutureOr<T> {
    pub fn value(value: T) -> Self {
        FutureOr::Value(Some(value))
    }
    pub fn future(future: DartFuture<T>) -> Self {
        FutureOr::Future(future)
    }
}

impl<T> Unpin for FutureOr<T> {}

impl<T: Clone> std::future::Future for FutureOr<T> {
    type Output = Result<T, DartError>;
    fn poll(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Self::Output> {
        match self.get_mut() {
            FutureOr::Value(value) => {
                std::task::Poll::Ready(Ok(value.take().expect("FutureOr polled twice")))
            }
            FutureOr::Future(future) => std::pin::Pin::new(future).poll(cx),
        }
    }
}

impl<T> std::fmt::Debug for FutureOr<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'FutureOr'")
    }
}

impl<T> DartNullable for FutureOr<T> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

impl<T, E> DartNullable for Result<T, E> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

struct Scheduled {
    id: i64,
    due: std::time::Instant,
    period: Option<std::time::Duration>,
    callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>,
    active: bool,
}

pub static SCHEDULER: std::sync::LazyLock<Isolate<std::cell::RefCell<Scheduler>>> =
    std::sync::LazyLock::new(|| {
        Isolate(std::cell::RefCell::new(Scheduler {
            microtasks: std::collections::VecDeque::new(),
            tasks: Vec::new(),
            timers: Vec::new(),
            next_id: 1,
        }))
    });

/// Dart's `scheduleMicrotask`.
pub fn schedule_microtask(callback: Box<dyn FnOnce() -> Result<(), DartError>>) {
    (**SCHEDULER).borrow_mut().microtasks.push_back(callback);
}

/// Runs everything that is due, and returns when nothing is.
///
/// Does **not** sleep waiting for a timer that is not due yet: sleeping is a
/// policy the host decides, and a translated program has no host here.
/// `next_due` says when to come back.
pub fn run_until_idle() {
    loop {
        let task = (**SCHEDULER).borrow_mut().microtasks.pop_front();
        match task {
            Some(task) => {
                // No caller to reach from the event loop: loud.
                task().unwrap();
                continue;
            }
            None => {}
        }
        // The spawned futures, each polled once; another pass whenever one
        // of them woke something (a completer another awaits).
        let tasks = std::mem::take(&mut (**SCHEDULER).borrow_mut().tasks);
        if !tasks.is_empty() {
            dart_woken();
            let waker = dart_waker();
            let mut cx = std::task::Context::from_waker(&waker);
            let mut pending = Vec::new();
            for mut task in tasks {
                if task.as_mut().poll(&mut cx).is_pending() {
                    pending.push(task);
                }
            }
            {
                let mut scheduler = (**SCHEDULER).borrow_mut();
                pending.append(&mut scheduler.tasks);
                scheduler.tasks = pending;
            }
            if dart_woken() || !(**SCHEDULER).borrow().microtasks.is_empty() {
                continue;
            }
        }
        let now = std::time::Instant::now();
        let due: Vec<(i64, std::rc::Rc<dyn Fn() -> Result<(), DartError>>)> = {
            let scheduler = (**SCHEDULER).borrow();
            scheduler
                .timers
                .iter()
                .filter(|t| t.active && t.due <= now)
                .map(|t| (t.id, t.callback.clone()))
                .collect()
        };
        if due.is_empty() {
            return;
        }
        for (id, callback) in due {
            // Rescheduled or dropped *before* the callback runs, so that a
            // callback cancelling its own timer wins over the reschedule.
            {
                let mut scheduler = (**SCHEDULER).borrow_mut();
                if let Some(timer) = scheduler.timers.iter_mut().find(|t| t.id == id) {
                    match timer.period {
                        Some(period) => timer.due = now + period,
                        None => timer.active = false,
                    }
                }
            }
            callback().unwrap();
        }
    }
}

/// When the next timer comes due, for a host that wants to sleep until then.
/// Runs a translated `main` to completion: polls its future, runs the
/// microtasks and due timers between polls, and sleeps until the next
/// timer when nothing else can make progress. Returns when the future is
/// done and the scheduler is idle. A `main` that waits on something no
/// timer or microtask will ever complete -- the engine's frame callback,
/// with no engine here -- is reported and abandoned: that is the ruler's
/// reading, not an error.
pub fn run_main<F: std::future::Future<Output = Result<(), DartError>>>(main: F) {
    let mut main = std::pin::pin!(main);
    let waker = dart_waker();
    let mut cx = std::task::Context::from_waker(&waker);
    let mut done = false;
    loop {
        if !done {
            match main.as_mut().poll(&mut cx) {
                std::task::Poll::Ready(Ok(())) => done = true,
                std::task::Poll::Ready(Err(error)) => {
                    eprintln!("dart2rust: main threw: {}", dart_message(&error));
                    return;
                }
                std::task::Poll::Pending => {}
            }
        }
        run_until_idle();
        if dart_woken() {
            continue;
        }
        match next_due() {
            Some(due) => {
                let now = std::time::Instant::now();
                if due > now {
                    std::thread::sleep(due - now);
                }
            }
            None => {
                if !done {
                    eprintln!(
                        "dart2rust: main is waiting on something no timer or microtask will complete"
                    );
                }
                return;
            }
        }
    }
}

pub fn next_due() -> Option<std::time::Instant> {
    (**SCHEDULER)
        .borrow()
        .timers
        .iter()
        .filter(|t| t.active)
        .map(|t| t.due)
        .min()
}

/// Dart's `Timer`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Timer {
    id: i64,
}

impl Timer {
    pub fn new(delay: Duration, callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>) -> Self {
        Timer::schedule(delay, callback, None)
    }

    pub fn periodic(
        period: Duration,
        callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>,
    ) -> Self {
        Timer::schedule(period, callback, Some(period))
    }

    /// Dart's `Timer.run`: a callback on the next turn of the loop.
    pub fn run(callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>) -> Self {
        Timer::new(Duration::ZERO, callback)
    }

    fn schedule(
        delay: Duration,
        callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>,
        period: Option<Duration>,
    ) -> Self {
        let wait = std::time::Duration::from_micros(delay.microseconds.max(0) as u64);
        let mut scheduler = (**SCHEDULER).borrow_mut();
        let id = scheduler.next_id;
        scheduler.next_id += 1;
        scheduler.timers.push(Scheduled {
            id,
            due: std::time::Instant::now() + wait,
            period: period.map(|p| std::time::Duration::from_micros(p.microseconds.max(0) as u64)),
            callback,
            active: true,
        });
        Timer { id }
    }

    pub fn cancel(&self) {
        let mut scheduler = (**SCHEDULER).borrow_mut();
        if let Some(timer) = scheduler.timers.iter_mut().find(|t| t.id == self.id) {
            timer.active = false;
        }
    }

    pub fn is_active(&self) -> bool {
        (**SCHEDULER)
            .borrow()
            .timers
            .iter()
            .any(|t| t.id == self.id && t.active)
    }
}

/// Dart's `Completer`: a future somebody else finishes.
///
/// Real, and correct against any executor. The value and the waker share one
/// cell; `complete` puts the value in and wakes whoever is waiting, and the
/// future takes the value when it is there. That is the whole of what a
/// completer is, and none of it needs a runtime -- which is why this one is
/// written out rather than left to the executor round.
///
/// `Rc`, not `Arc`: everything here belongs to one isolate. See `Isolate`.
pub struct Completer<T> {
    future: DartFuture<T>,
}

/// A completer prints as its kind and compares by identity: a struct holding
/// one (`SchedulerBinding._nextFrameCompleter`) derives both.
impl<T> std::fmt::Debug for Completer<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'Completer'")
    }
}

impl<T> PartialEq for Completer<T> {
    fn eq(&self, other: &Self) -> bool {
        self.future == other.future
    }
}

/// A `Completer` is a handle on its future: cloning shares.
impl<T> Clone for Completer<T> {
    fn clone(&self) -> Self {
        Completer {
            future: self.future.clone(),
        }
    }
}

impl<T: DartNullable> Default for Completer<T> {
    fn default() -> Self {
        Completer::new()
    }
}

impl<T: DartNullable> Completer<T> {
    pub fn new() -> Self {
        Completer {
            future: DartFuture::pending(),
        }
    }

    /// `completeError(error, [stackTrace])`: the future fails with it.
    pub fn complete_error(&self, error: std::rc::Rc<dyn Object>, _stack: Option<StackTrace>) {
        if self.future.is_done() {
            panic!("Completer completed twice");
        }
        self.future.resolve(Err(error));
    }

    /// Dart's `Completer.sync`, which completes its future synchronously
    /// rather than through a microtask; the same thing here.
    pub fn sync() -> Self {
        Completer::new()
    }

    /// `complete([value])`. The slot is Dart's `T?` as translated code
    /// spells it, `<T as DartNullable>::Or`: for a `Completer<ByteData?>`
    /// that is one `Option`, not two, and its `null` completes the future
    /// with `None`; a `Completer<void>` is completed with `Some(())`.
    pub fn complete(&self, value: <T as DartNullable>::Or) {
        if self.future.is_done() {
            panic!("Completer completed twice");
        }
        let value = T::option(value)
            .or_else(T::dart_null)
            .expect("Completer completed with null for a non-nullable type");
        self.future.resolve(Ok(value));
    }

    pub fn is_completed(&self) -> bool {
        self.future.is_done()
    }

    /// `future`: the same shared future every time.
    pub fn future(&self) -> DartFuture<T> {
        self.future.clone()
    }
}

/// Dart's `RegExp`, as a name and a pattern and nothing else.
///
/// There is no regular-expression engine here and writing one is not this
/// project's job. What upstream does with a `RegExp` is match and replace, and
/// both `panic!` with the pattern in the message -- the same answer the
/// backend gives for a method it cannot translate, and for the same reason: a
/// loud failure at the point of use beats a quiet wrong answer, and beats a
/// missing name that stops a thousand lines from compiling.
///
/// Pulling in a regex crate would work and is deliberately not done: the
/// generated crate has no dependencies, which is what makes it possible to say
/// that everything in it came from the Dart or from this file.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct RegExp {
    pub pattern: String,
}

impl RegExp {
    /// `RegExp(source, {multiLine, caseSensitive, unicode, dotAll})`: the
    /// flags are carried and not yet honoured.
    pub fn new(
        pattern: String,
        _multi_line: bool,
        _case_sensitive: bool,
        _unicode: bool,
        _dot_all: bool,
    ) -> Self {
        RegExp { pattern }
    }

    /// `firstMatch(input)`: none, until there is an engine (see `RegExpMatch`).
    pub fn first_match(&self, _input: String) -> Option<RegExpMatch> {
        None
    }

    pub fn has_match(&self, _input: String) -> bool {
        panic!("RegExp has no engine here: {}", self.pattern)
    }

    pub fn string_match(&self, _input: String) -> Option<String> {
        panic!("RegExp has no engine here: {}", self.pattern)
    }

    pub fn all_matches(&self, _input: &str) -> Vec<String> {
        panic!("RegExp has no engine here: {}", self.pattern)
    }
}

/// Dart's error and exception classes.
///
/// One shape for all of them: a message, and a `Display` that prints what Dart
/// prints. They are thrown and caught by *type* upstream, and the `Result<T,
/// E>` the backend emits carries the type, so nothing else about them is
/// reached.
macro_rules! dart_error {
    ($name:ident, $prefix:literal) => {
        #[derive(Clone, Debug, Default, PartialEq, Eq)]
        pub struct $name {
            pub message: String,
        }

        impl $name {
            pub fn new(message: String) -> Self {
                $name { message }
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                if self.message.is_empty() {
                    f.write_str($prefix)
                } else {
                    write!(f, "{}: {}", $prefix, self.message)
                }
            }
        }

        impl DartEq for $name {
            fn dart_eq(&self, other: &Self) -> bool {
                self == other
            }
        }
    };
}

/// `Exception([dynamic message])`: the message as translated code spells a
/// `dynamic`, printed as Dart's `toString` would.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Exception {
    pub message: String,
}

impl Exception {
    pub fn new(message: std::rc::Rc<dyn Object>) -> Self {
        Exception {
            message: dart_message(&message),
        }
    }
}

impl fmt::Display for Exception {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.message.is_empty() {
            f.write_str("Exception")
        } else {
            write!(f, "Exception: {}", self.message)
        }
    }
}

/// A `dynamic message` as `Exception.toString` prints it: nothing for null,
/// a string as itself, anything else by its own text.
pub fn dart_message(message: &std::rc::Rc<dyn Object>) -> String {
    let object: &dyn Object = message.as_ref();
    if object.as_any().is::<Null>() {
        return String::new();
    }
    match object.as_any().downcast_ref::<String>() {
        Some(text) => text.clone(),
        None => format!("{}", object),
    }
}
dart_error!(StateError, "Bad state");
dart_error!(Error, "Error");

/// `String.fromCharCodes(codes)`: UTF-16 code units to a String.
pub fn string_from_char_codes(codes: Vec<i64>) -> String {
    let units: Vec<u16> = codes.iter().map(|c| *c as u16).collect();
    String::from_utf16_lossy(&units)
}

/// `Object()`: a fresh object with nothing but an identity -- `final
/// _clockKey = Object();` uses one as a zone key.
pub fn new_object() -> std::rc::Rc<dyn Object> {
    std::rc::Rc::new(())
}

/// `dart:io`'s `Platform` statics, as functions: a static getter upstream is
/// a call here (see the backend's `_staticRead`).
/// `dart:developer`'s `log(message, {time, sequenceNumber, level, name,
/// zone, error, stackTrace})`, the named ones filled in by the front end in
/// declaration order. Printed to stderr, which is where a developer log
/// goes without an observatory.
pub fn log(
    message: String,
    _time: Option<DateTime>,
    _sequence_number: Option<i64>,
    _level: i64,
    name: String,
    _zone: Option<Zone>,
    error: Option<std::rc::Rc<dyn Object>>,
    _stack_trace: Option<StackTrace>,
) {
    if name.is_empty() {
        eprintln!("{}", message);
    } else {
        eprintln!("[{}] {}", name, message);
    }
    if let Some(e) = error {
        eprintln!("  error: {:?}", e);
    }
}

/// `Uint8List.view(buffer, [offsetInBytes, length])`: a window copied out
/// of the bytes (a buffer here is the bytes themselves).
pub fn uint8_list_view(buffer: Vec<u8>, offset: i64, length: Option<i64>) -> Vec<u8> {
    let start = (offset.max(0) as usize).min(buffer.len());
    let end = match length {
        Some(n) => (start + n.max(0) as usize).min(buffer.len()),
        None => buffer.len(),
    };
    buffer[start..end].to_vec()
}

/// `TypedData.buffer` on a list of ints: the bytes, one per element, which
/// is what a `Uint8List` behind a `List<int>` holds.
pub trait DartTypedList {
    fn buffer(&self) -> Vec<u8>;
}

impl DartTypedList for Vec<i64> {
    fn buffer(&self) -> Vec<u8> {
        self.iter().map(|v| *v as u8).collect()
    }
}

impl DartTypedList for Vec<u8> {
    fn buffer(&self) -> Vec<u8> {
        self.clone()
    }
}

/// `ByteBuffer.asUint8List(offset, length)` and its siblings on the bytes
/// a buffer is here: windows copied out, in the element width asked for.
pub trait DartByteBuffer {
    fn as_uint8_list(&self, offset: i64, length: Option<i64>) -> Vec<u8>;
    fn as_int8_list(&self, offset: i64, length: Option<i64>) -> Vec<i8>;
    fn as_byte_data(&self, offset: i64, length: Option<i64>) -> ByteData;
    fn as_int32_list(&self, offset: i64, length: Option<i64>) -> Vec<i32>;
    fn as_float32_list(&self, offset: i64, length: Option<i64>) -> Vec<f32>;
    fn as_float64_list(&self, offset: i64, length: Option<i64>) -> Vec<f64>;
}

fn byte_window(bytes: &[u8], offset: i64, length: Option<i64>, width: usize) -> &[u8] {
    let start = (offset.max(0) as usize).min(bytes.len());
    let end = match length {
        Some(n) => (start + n.max(0) as usize * width).min(bytes.len()),
        None => bytes.len(),
    };
    &bytes[start..end]
}

impl DartByteBuffer for Vec<u8> {
    fn as_uint8_list(&self, offset: i64, length: Option<i64>) -> Vec<u8> {
        byte_window(self, offset, length, 1).to_vec()
    }

    fn as_int8_list(&self, offset: i64, length: Option<i64>) -> Vec<i8> {
        byte_window(self, offset, length, 1)
            .iter()
            .map(|b| *b as i8)
            .collect()
    }

    fn as_byte_data(&self, offset: i64, length: Option<i64>) -> ByteData {
        ByteData {
            bytes: byte_window(self, offset, length, 1).to_vec(),
        }
    }

    fn as_int32_list(&self, offset: i64, length: Option<i64>) -> Vec<i32> {
        byte_window(self, offset, length, 4)
            .chunks_exact(4)
            .map(|c| i32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect()
    }

    fn as_float32_list(&self, offset: i64, length: Option<i64>) -> Vec<f32> {
        byte_window(self, offset, length, 4)
            .chunks_exact(4)
            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect()
    }

    fn as_float64_list(&self, offset: i64, length: Option<i64>) -> Vec<f64> {
        byte_window(self, offset, length, 8)
            .chunks_exact(8)
            .map(|c| f64::from_le_bytes([c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7]]))
            .collect()
    }
}

/// `utf8.decoder`.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Utf8Decoder;

impl Utf8Decoder {
    /// `convert(codeUnits, [start, end])`.
    pub fn convert(&self, code_units: Vec<i64>, start: i64, end: Option<i64>) -> String {
        let s = (start.max(0) as usize).min(code_units.len());
        let e = end
            .map(|n| (n.max(0) as usize).min(code_units.len()))
            .unwrap_or(code_units.len());
        Utf8Codec.decode(code_units[s..e].to_vec(), Some(true))
    }

    /// `utf8.decoder.fuse(other)`: the two conversions in a row.
    pub fn fuse<U: 'static>(&self, next: Converter<String, U>) -> Converter<Vec<i64>, U> {
        Converter::new(std::rc::Rc::new(move |bytes: Vec<i64>| {
            next.convert(Utf8Decoder.convert(bytes, 0, None))
        }))
    }
}

/// `dart:convert`'s `Converter<S, T>`, as a value: what a `fuse` makes, and
/// what a codec's `encoder`/`decoder` are. It holds the conversion.
pub struct Converter<S, T> {
    convert: std::rc::Rc<dyn Fn(S) -> Result<T, DartError>>,
}

impl<S, T> Clone for Converter<S, T> {
    fn clone(&self) -> Self {
        Converter {
            convert: self.convert.clone(),
        }
    }
}

impl<S, T> std::fmt::Debug for Converter<S, T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'Converter'")
    }
}

impl<S, T> PartialEq for Converter<S, T> {
    fn eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.convert, &other.convert)
    }
}

impl<S, T> DartNullable for Converter<S, T> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

impl<S: 'static, T: 'static> Converter<S, T> {
    pub fn new(convert: std::rc::Rc<dyn Fn(S) -> Result<T, DartError>>) -> Self {
        Converter { convert }
    }

    /// `convert(input)`.
    pub fn convert(&self, input: S) -> Result<T, DartError> {
        (self.convert)(input)
    }

    /// `fuse(other)`: this conversion, then the other's.
    pub fn fuse<U: 'static>(&self, next: Converter<T, U>) -> Converter<S, U> {
        let first = self.clone();
        Converter::new(std::rc::Rc::new(move |input: S| {
            next.convert(first.convert(input)?)
        }))
    }
}

